#[cfg(test)]
mod extend_201202_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_extend_201202_codec() {
        let original = Extend201202 {
            insufficient_security_id: "a".repeat(8),
            no_security: 123456,
            underlying_security_id: "a".repeat(8),
            underlying_security_id_source: "a".repeat(4),
            delivery_qty: -123456789,
            subst_cash: -123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let mut bytes = buf.freeze();

        let decoded = Extend201202::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
    }
}
